#include <stdio.h>
#include <stdlib.h>
#include <malloc.h>

#define OK   1
#define ERROR  0
#define TRUE 1
#define FALSE 0

typedef int ElemType;
typedef struct Node    /*结点类型定义*/ 
{ 
	ElemType data;
	struct Node  * next;
}Node, *LinkList;  /* LinkList为结构指针类型*/

void create_clinklist(LinkList l)/*创建循环链表*/
{
	int num;
	Node *p;
	l->data=-1;
	l->next=l;
	printf("请输入循环链表的元素 (以-1结束):\n");
	scanf("%d",&num);
	while(num != -1)
	{
		p=(Node*)malloc(sizeof(struct Node));
		p->data=num;
		p->next=l->next;
		l->next=p;
		scanf("%d",&num);
	}
}

/* 示例：建表函数读一串整数（-1 结束），每读一个就插在头结点后面。
   头结点的指针域最终绕回头结点本身——这就是"循环"。 */
int main(void)
{
    Node head;
    Node *p;
    Node *last = &head;

    head.data = -1;
    head.next = &head;
    create_clinklist(&head);

    printf("循环链表的内容: ");
    for (p = head.next; p != &head; p = p->next)
    {
        printf("%d ", p->data);
        last = p;
    }
    printf("\n最后一个结点指回头结点: %d\n", last->next == &head ? 1 : 0);
    return 0;
}

