    DNode head;
    DNode *p;

    CreateList(&head);

    printf("正向 (next): ");
    for (p = head.next; p != &head; p = p->next)
        printf("%c ", p->data);
    printf("\n反向 (prior): ");
    for (p = head.prior; p != &head; p = p->prior)
        printf("%c ", p->data);
    printf("\n");
    return 0;
}

