#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <malloc.h>

#define TRUE 1
#define FALSE 0
typedef int QueueElementType;
typedef struct Node
{
    QueueElementType data;
    struct Node *next;
} LinkQueueNode;
typedef struct
{
    LinkQueueNode *front;
    LinkQueueNode *rear;
} LinkQueue;

/* ===== 以下来自 ch03-3.18 ===== */
int InitQueue(LinkQueue *Q)
{ 
	/* 将Q初始化为一个空的链队列 */
	Q->front=(LinkQueueNode *)malloc(sizeof(LinkQueueNode));
	if(Q->front!=NULL)
	{
		Q->rear=Q->front;
		Q->front->next=NULL;
 		return(TRUE);
	}
	else  	return(FALSE);    /* 溢出！*/
}

/* ===== 以下来自 ch03-3.19 ===== */
int EnterQueue(LinkQueue *Q,QueueElementType x)
{  
	/* 将数据元素x插入到队列Q中 */
	LinkQueueNode  *NewNode;
	NewNode=(LinkQueueNode *)malloc(sizeof(LinkQueueNode));
	if(NewNode!=NULL)
	{
		NewNode->data=x;
		NewNode->next=NULL;
		Q->rear->next=NewNode;
	  	Q->rear=NewNode;
		return(TRUE);
	}
	else  return(FALSE);    /* 溢出！*/
}

/* ===== 以下来自 ch03-3.20 ===== */
int DeleteQueue(LinkQueue *Q,QueueElementType *x)
{  
	/* 将队列Q的队头元素出队，并存放到x所指的存储空间中 */
	LinkQueueNode *p;
	if(Q->front==Q->rear)
		return(FALSE);
	p=Q->front->next;
	Q->front->next=p->next;  /* 队头元素p出队 */
	if(Q->rear==p)  /* 如果队中只有一个元素p，则p出队后成为空队 */
	Q->rear=Q->front;  
	*x=p->data;
	free(p);   /* 释放存储空间 */
	return(TRUE);	
}

/* 示例：链队列带着头结点，front 指向头结点，空队列就是 front == rear。 */
int main(void)
{
    LinkQueue Q;
    int i;
    int x;

    InitQueue(&Q);
    for (i = 1; i <= 3; i++)
        EnterQueue(&Q, i * 10);

    printf("出队顺序: ");
    while (DeleteQueue(&Q, &x))
        printf("%d ", x);
    printf("\n空队再出队: %d\n", DeleteQueue(&Q, &x));
    return 0;
}

