#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <malloc.h>

#define TRUE 1
#define FALSE 0
#define Stack_Size 50
typedef char StackElementType;
typedef struct
{
    StackElementType elem[Stack_Size];
    int top;
} SeqStack;

/* ===== 以下来自 ch03-3.1 ===== */
void InitStack(SeqStack *S)
{
	/*构造一个空栈S*/
	S->top = -1;
}

/* ===== 以下来自 ch03-3.2 ===== */
int Push(SeqStack *S,StackElementType x)
{
	if(S->top==(Stack_Size-1))  
		return(FALSE);  /*栈已满*/
	S->top++;
	S->elem[S->top]=x;
	return(TRUE);
}

/* ===== 以下来自 ch03-3.3 ===== */
int Pop(SeqStack *S,StackElementType *x)
{  
	/* 将栈S的栈顶元素弹出，放到x所指的存储空间中 */
	if(S->top==-1)  /*栈为空*/
		return(FALSE);
	else
	{
		*x=S->elem[S->top];
		S->top--;    /* 修改栈顶指针 */
  		return(TRUE);
	}
}

/* ===== 以下来自 ch03-3.4 ===== */
int GetTop(SeqStack *S, StackElementType *x)
{  
	/* 将栈S的栈顶元素弹出，放到x所指的存储空间中，但栈顶指针保持不变 */
	if(S->top==-1)  /*栈为空*/
		return(FALSE);
	else
	{
		*x = S->elem[S->top];
		return(TRUE);
	}	
}

/* 示例把顺序栈的四个基本运算串起来：入栈、取栈顶、出栈，空栈再出栈会返回 FALSE。 */
int main(void)
{
    SeqStack S;
    char word[] = "abcde";
    char x;
    int i;

    InitStack(&S);
    for (i = 0; word[i] != '\0'; i++)
        Push(&S, word[i]);

    printf("入栈后元素个数: %d\n", S.top + 1);
    GetTop(&S, &x);
    printf("栈顶元素: %c\n", x);
    printf("出栈顺序: ");
    while (S.top != -1)
    {
        Pop(&S, &x);
        printf("%c ", x);
    }
    printf("\n空栈再出栈: %d\n", Pop(&S, &x));
    return 0;
}

