#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <malloc.h>

#define TRUE 1
#define FALSE 0
#define MAXSIZE 50
typedef int QueueElementType;
typedef struct
{
    QueueElementType element[MAXSIZE];
    int front;
    int rear;
} SeqQueue;

/* ===== 以下来自 ch03-3.21 ===== */
void InitQueue(SeqQueue *Q)
{  
	/* 将*Q初始化为一个空的循环队列 */
	Q->front=Q->rear=0;
}

/* ===== 以下来自 ch03-3.22 ===== */
int EnterQueue(SeqQueue *Q,QueueElementType x)
{  
	/*将元素x入队*/
	if((Q->rear+1)%MAXSIZE==Q->front)  /*队列已经满了*/
		return(FALSE);
	Q->element[Q->rear]=x;
	Q->rear=(Q->rear+1)%MAXSIZE;  /* 重新设置队尾指针 */
	return(TRUE);  /*操作成功*/
}

