int main(void)
{
    SeqStack S;
    char word[] = "abcde";
    char x;
    int i;

    InitStack(&S);
    for (i = 0; word[i] != '\0'; i++)
        Push(&S, word[i]);

    printf("入栈后元素个数: %d\n", S.top + 1);
    GetTop(&S, &x);
    printf("栈顶元素: %c\n", x);
    printf("出栈顺序: ");
    while (S.top != -1)
    {
        Pop(&S, &x);
        printf("%c ", x);
    }
    printf("\n空栈再出栈: %d\n", Pop(&S, &x));
    return 0;
}

