		{
			Temp->top++;
			Temp->stack[Temp->top]=Enter->stack[Enter->top];
			Enter->stack[Enter->top]=NULL;
			Enter->top--;
		} 
		p=Enter->stack[Enter->top];
		Enter->stack[Enter->top]=NULL;
		Enter->top--;
		while(Temp->top>=1)
		{
			Enter->top++;
			Enter->stack[Enter->top]=Temp->stack[Temp->top];
			Temp->stack[Temp->top]=NULL;
			Temp->top--;
		}
		PRINT(p,room);
		/*判断通道上是否有车及车站是否已满*/
		if((W->head!=W->rear)&&Enter->top<MAX) /*便道的车辆进入车场*/
		{ 
			q=W->head->next;
