/*链式存储方式下的模式匹配，每个字符用一结点表示*/

typedef struct Block{
	char   ch;
	struct Block   *next;
}Block;

typedef struct {
	Block   *head;
	Block   *tail;
	int     len;
}BLString;

/* 示例：链式串每个字符占一个结点，head/tail 记账，len 记长度。 */
int main(void)
{
    BLString s;
    Block *node;
    char source[] = "abc";
    int i;

    s.head = NULL;
    s.tail = NULL;
    s.len = 0;
    for (i = 0; source[i] != '\0'; i++)
    {
        node = (Block *)malloc(sizeof(Block));
        node->ch = source[i];
        node->next = NULL;
        if (s.head == NULL)
            s.head = node;
        else
            s.tail->next = node;
        s.tail = node;
        s.len++;
    }

    printf("串内容: ");
    for (node = s.head; node != NULL; node = node->next)
        printf("%c", node->ch);
    printf("\n串长度: %d\n", s.len);
    return 0;
}

