	int  next;                   /* 静态链域 */ 
} RecordType1;

typedef struct 
{
	RecordType1  r[LIST_SIZE+1];  /* r[0]为头结点 */
	int length;
	int keynum;
}SLinkList;                  /* 静态链表 */

typedef int PVector[RADIX];

int main(void)
{
    SLinkList L;
    int i;

    L.length = 2;
    L.keynum = 3;
    for (i = 0; i <= LIST_SIZE; i++)
    {
        L.r[i].next = 0;
        L.r[i].other_data = 0;
    }

    L.r[1].other_data = 1;
    L.r[1].key[1] = 4; L.r[1].key[2] = 9; L.r[1].key[3] = 7;
